n = 7
all_edges = [(i,j) for i in range(n) for j in range(i+1, n)]
fixed = {(0,6), (1,5)}

def is_triangle_free(edge_set):
    for i in range(n):
        for j in range(i+1, n):
            if (i,j) not in edge_set: continue
            for k in range(j+1, n):
                if (i,k) in edge_set and (j,k) in edge_set:
                    return False
    return True

def is_maximal(edge_set):
    for (i,j) in all_edges:
        if (i,j) not in edge_set:
            new_set = edge_set | {(i,j)}
            if is_triangle_free(new_set):
                return False
    return True

remaining_edges = [e for e in all_edges if e not in fixed]
found = []
for mask in range(1 << len(remaining_edges)):
    edge_set = set(fixed)
    for idx, e in enumerate(remaining_edges):
        if mask & (1 << idx):
            edge_set.add(e)
    if is_triangle_free(edge_set) and is_maximal(edge_set):
        found.append(sorted(edge_set))

print("Total maximal triangle-free graphs:", len(found))
for g in found:
    print(g, "edges:", len(g))

